package dev.mineagent.runtime.worker.resources;

import com.fasterxml.jackson.databind.JsonNode;
import dev.mineagent.runtime.core.resources.ResourceLibrary;
import org.jsoup.Jsoup;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.io.*;

/** Read-only, page/cell/frame-selectable resource parsing. Never invokes arbitrary code or Python. */
public final class ResourceParser {
 public static Map<String,Object> read(ResourceLibrary library,UUID id,JsonNode args)throws Exception{
  var resource=library.get(id);Path file=library.data(id);String mode=args.path("mode").asText("auto"),mime=kind(file,resource.mime(),resource.name());var out=new LinkedHashMap<String,Object>(ResourceLibrary.view(resource));out.put("status","OBSERVED");out.put("detectedType",mime);out.put("executed",false);
  if(mime.equals("pdf")){pdf(library,resource,file,args,out);return out;}
  if(mime.equals("image")){var image=ResourceImages.prepare(library.read(id),List.of(),"low");out.put("width",image.sourceWidth());out.put("height",image.sourceHeight());out.put("visualTool","inspect_image");return out;}
  if(mime.equals("xlsx")){spreadsheet(file,args,out);return out;}
  if(mime.equals("video")){video(library,resource,file,args,out);return out;}
  if(mime.equals("audio")){out.put("transcriptionTool","transcribe_resource");out.put("selection","start_seconds and duration_seconds");return out;}
  if(mime.equals("binary")){out.put("status","BINARY_RESOURCE_AVAILABLE");out.put("downloadTool","download_resource");return out;}
  if(Files.size(file)>8*1024*1024)throw new IllegalArgumentException("RESOURCE_TEXT_BUDGET");String text=Files.readString(file,StandardCharsets.UTF_8);
  if(mime.equals("html")){var doc=Jsoup.parse(text,resource.source());doc.select("script,style,noscript,nav,header,footer,iframe,form").remove();out.put("title",doc.title());var tables=doc.select("table");var catalog=new ArrayList<Object>();for(int i=0;i<tables.size();i++)catalog.add(Map.of("index",i,"rows",tables.get(i).select("tr").size()));out.put("tables",catalog);
   if(mode.equals("table")){int table=integer(args,"table",0,0,Math.max(0,tables.size()-1));if(tables.isEmpty())throw new IllegalArgumentException("RESOURCE_TABLE_NOT_FOUND");cells(ResourceTables.html(tables.get(table)),args,out);out.put("mergedCells","rowspan/colspan expanded to occupied cells");return out;}
   var images=new ArrayList<Object>();for(var image:doc.select("img[src],img[data-src]")){String url=image.absUrl(image.hasAttr("src")?"src":"data-src");if(url.startsWith("https://"))images.add(Map.of("url",url,"alt",image.attr("alt"),"tool","inspect_image"));}out.put("images",images.stream().limit(128).toList());out.put("imagesMore",images.size()>128);var links=new ArrayList<Object>();for(var link:doc.select("a[href]")){String url=link.absUrl("href");if(url.startsWith("https://"))links.add(Map.of("url",url,"label",link.text()));}out.put("links",links.stream().limit(128).toList());var main=doc.selectFirst("article,main,#mw-content-text,.item-content");text=(main==null?doc.body():main).wholeText();}
  if(mime.equals("csv")||mime.equals("tsv")||mode.equals("table")){cells(csv(text,mime.equals("tsv")?'\t':','),args,out);return out;}page(text,args,out);return out;
 }
 public static String kind(Path file,String supplied,String name)throws IOException{
  byte[] head;try(var in=Files.newInputStream(file)){head=in.readNBytes(16);}String mime=supplied.toLowerCase(Locale.ROOT),lower=name.toLowerCase(Locale.ROOT);String prefix=new String(head,StandardCharsets.ISO_8859_1);
  if(prefix.startsWith("%PDF-"))return "pdf";if(mime.startsWith("image/")||prefix.startsWith("\u0089PNG")||head.length>2&&(head[0]&255)==255&&(head[1]&255)==216||prefix.startsWith("GIF8"))return "image";
  if(lower.endsWith(".xlsx")||mime.contains("spreadsheetml"))return "xlsx";if(lower.endsWith(".csv")||mime.contains("text/csv"))return "csv";if(lower.endsWith(".tsv"))return "tsv";
  if(mime.startsWith("video/")||lower.matches(".*\\.(mp4|mov|mkv|webm|avi)$"))return "video";if(mime.startsWith("audio/")||lower.matches(".*\\.(wav|mp3|ogg|flac|m4a)$"))return "audio";
  if(mime.contains("html")||lower.endsWith(".html")||prefix.stripLeading().startsWith("<!DOCTYPE"))return "html";if(mime.startsWith("text/")||mime.contains("json")||mime.contains("xml")||lower.matches(".*\\.(txt|md|json|xml|log|js|java)$"))return "text";return "binary";
 }
 private static void pdf(ResourceLibrary library,ResourceLibrary.Resource source,Path file,JsonNode args,Map<String,Object> out)throws Exception{
  try(var doc=org.apache.pdfbox.Loader.loadPDF(file.toFile())){if(!doc.getCurrentAccessPermission().canExtractContent())throw new IllegalArgumentException("PDF_EXTRACTION_NOT_ALLOWED");int total=doc.getNumberOfPages(),start=integer(args,"page",1,1,Math.max(1,total)),count=integer(args,"page_count",1,1,8);out.put("totalPages",total);out.put("page",start);out.put("nextPage",start+count<=total?start+count:-1);
   var pages=new ArrayList<Object>();for(int i=start;i<=Math.min(total,start+count-1);i++){var stripper=new org.apache.pdfbox.text.PDFTextStripper();stripper.setSortByPosition(true);stripper.setStartPage(i);stripper.setEndPage(i);var row=new LinkedHashMap<String,Object>();row.put("page",i);page(stripper.getText(doc),args,row);if(args.path("mode").asText().equals("table"))ResourceTables.pdf(doc,i,args,row);if(args.path("render").asBoolean(false)){var box=doc.getPage(i-1).getCropBox();float scale=(float)Math.min(2,Math.sqrt(4_194_304.0/(box.getWidth()*box.getHeight())));if(!Float.isFinite(scale)||scale<=0)throw new IllegalArgumentException("PDF_PAGE_GEOMETRY");var image=new org.apache.pdfbox.rendering.PDFRenderer(doc).renderImage(i-1,scale);try{var png=ResourceImages.encode(image,4_194_304);row.put("image",ResourceLibrary.view(library.save(source.name()+" page "+i,"image/png",source.source(),png.bytes(),source.id(),Map.of("page",Integer.toString(i)))));}finally{image.flush();}}pages.add(row);}out.put("pages",pages);
  }
 }
 private static void spreadsheet(Path file,JsonNode args,Map<String,Object> out)throws Exception{
  try(var workbook=org.apache.poi.ss.usermodel.WorkbookFactory.create(file.toFile(),null,true)){var sheets=new ArrayList<Object>();for(int i=0;i<workbook.getNumberOfSheets();i++)sheets.add(Map.of("index",i,"name",workbook.getSheetName(i)));out.put("sheets",sheets);int selected=integer(args,"table",0,0,Math.max(0,workbook.getNumberOfSheets()-1));var sheet=workbook.getSheetAt(selected);int start=integer(args,"row_start",0,0,1_000_000),count=integer(args,"row_count",32,1,128),column=integer(args,"column_start",0,0,16383),columns=integer(args,"column_count",16,1,64);var cells=new ArrayList<Object>();var formatter=new org.apache.poi.ss.usermodel.DataFormatter(Locale.ROOT);
   for(int r=start;r<=Math.min(sheet.getLastRowNum(),start+count-1);r++){var row=sheet.getRow(r);if(row==null)continue;for(int c=column;c<column+columns;c++){var cell=row.getCell(c);if(cell!=null)cells.add(Map.of("row",r,"column",c,"address",cell.getAddress().formatAsString(),"text",formatter.formatCellValue(cell),"formula",cell.getCellType()==org.apache.poi.ss.usermodel.CellType.FORMULA));}}out.put("cells",cells);out.put("totalRows",sheet.getLastRowNum()+1);out.put("nextRow",start+count<=sheet.getLastRowNum()?start+count:-1);out.put("formulaExecution",false);
  }
 }
 private static void video(ResourceLibrary library,ResourceLibrary.Resource source,Path file,JsonNode args,Map<String,Object> out)throws Exception{
  var frames=new ArrayList<Object>();var times=new ArrayList<Double>();if(args.path("times").isArray())for(var value:args.path("times")){if(!value.isNumber()||!Double.isFinite(value.doubleValue())||value.doubleValue()<0)throw new IllegalArgumentException("VIDEO_FRAME_TIME");times.add(value.doubleValue());}if(times.isEmpty())times.add(0.0);if(times.size()>8)throw new IllegalArgumentException("VIDEO_FRAME_COUNT");
  try(var channel=org.jcodec.common.io.NIOUtils.readableChannel(file.toFile())){var grab=org.jcodec.api.FrameGrab.createFrameGrab(channel);double duration=grab.getVideoTrack().getMeta().getTotalDuration();out.put("durationSeconds",duration);for(double time:times){if(time>duration)throw new IllegalArgumentException("VIDEO_TIME_OUTSIDE_DURATION");grab.seekToSecondPrecise(time);var picture=grab.getNativeFrame();if(picture==null)throw new IOException("VIDEO_FRAME_MISSING");var image=org.jcodec.scale.AWTUtil.toBufferedImage(picture);try{var png=ResourceImages.encode(image,2_359_296);frames.add(Map.of("timeSeconds",time,"image",ResourceLibrary.view(library.save(source.name()+" @ "+time,"image/png",source.source(),png.bytes(),source.id(),Map.of("timeSeconds",Double.toString(time))))));}finally{image.flush();}}}catch(org.jcodec.api.JCodecException|IOException|UnsupportedOperationException codec){frames.clear();for(double time:times){byte[] decoded=NativeMediaDecoder.frame(library.dataRoot(),file,time);var png=ResourceImages.prepare(decoded,List.of(),"high").image();frames.add(Map.of("timeSeconds",time,"image",ResourceLibrary.view(library.save(source.name()+" @ "+time,"image/png",source.source(),png.bytes(),source.id(),Map.of("timeSeconds",Double.toString(time),"decoder","ffmpeg")))));}out.put("decoder","JAVA_MANAGED_FFMPEG");}out.put("frames",frames);out.put("visualTool","compare_images");
 }
 public static void page(String text,JsonNode args,Map<String,Object> out){int start=integer(args,"offset",0,0,text.length()),length=integer(args,"length",16000,1,64000),end=Math.min(text.length(),start+length);if(end<text.length()&&end>start&&Character.isHighSurrogate(text.charAt(end-1)))end--;out.put("text",text.substring(start,end));out.put("offset",start);out.put("totalCharacters",text.length());out.put("nextOffset",end<text.length()?end:-1);}
 static void cells(List<List<String>> rows,JsonNode args,Map<String,Object> out){int start=integer(args,"row_start",0,0,rows.size()),count=integer(args,"row_count",32,1,128),column=integer(args,"column_start",0,0,16383),columns=integer(args,"column_count",16,1,64);var cells=new ArrayList<Object>();for(int r=start;r<Math.min(rows.size(),start+count);r++)for(int c=column;c<Math.min(rows.get(r).size(),column+columns);c++)cells.add(Map.of("row",r,"column",c,"text",rows.get(r).get(c)));out.put("cells",cells);out.put("totalRows",rows.size());out.put("nextRow",start+count<rows.size()?start+count:-1);}
 static List<List<String>> csv(String source,char delimiter){var rows=new ArrayList<List<String>>();var row=new ArrayList<String>();var value=new StringBuilder();boolean quote=false;for(int i=0;i<source.length();i++){char c=source.charAt(i);if(c=='"'){if(quote&&i+1<source.length()&&source.charAt(i+1)=='"'){value.append('"');i++;}else quote=!quote;}else if(!quote&&(c==delimiter||c=='\n'||c=='\r')){row.add(value.toString());value.setLength(0);if(c!=delimiter){rows.add(List.copyOf(row));row.clear();if(c=='\r'&&i+1<source.length()&&source.charAt(i+1)=='\n')i++;}}else value.append(c);if(rows.size()>100000||row.size()>16384||value.length()>1_000_000)throw new IllegalArgumentException("TABLE_PARSE_BUDGET");}if(quote)throw new IllegalArgumentException("CSV_UNCLOSED_QUOTE");if(!value.isEmpty()||!row.isEmpty()){row.add(value.toString());rows.add(List.copyOf(row));}return rows;}
 static int integer(JsonNode args,String key,int fallback,int min,int max){if(!args.has(key))return fallback;var value=args.get(key);if(!value.isIntegralNumber()||!value.canConvertToInt()||value.intValue()<min||value.intValue()>max)throw new IllegalArgumentException("RESOURCE_FIELD "+key+": expected "+min+".."+max);return value.intValue();}
 private ResourceParser(){}
}
